function currentAffairs(){return `<section class="hero"><h1>🗞️ Daily Current Affairs</h1><p>Fresh headlines and optional AI quiz in Indian languages.</p></section><div class="card"><div class="grid"><select id="caLang" class="field"><option>English</option><option>Telugu</option><option>Hindi</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><select id="caCat" class="field"><option>All</option><option>India</option><option>World</option><option>Business</option><option>Technology</option><option>Science</option><option>Sports</option><option>Education</option></select><select id="caCount" class="field"><option>5</option><option>10</option><option selected>12</option><option>15</option><option>20</option></select></div><button class="btn" onclick="loadCurrentAffairs()">📰 Load Today's Current Affairs</button><div id="caOut" style="margin-top:15px"></div></div>`}async function loadCurrentAffairs(){const lang=$('#caLang').value,cat=$('#caCat').value,count=Number($('#caCount').value);$('#caOut').innerHTML='<div class="notice">Fetching today\'s headlines…</div>';try{const j=await api('live-rss',{query:cat==='All'?'India':cat,language:lang,limit:Math.min(20,count*2)});let items=j.items||[];if(cat!=='All'){const terms={India:['india','indian'],World:['world','international','global'],Business:['business','economy','market','finance'],Technology:['technology','tech','ai','software'],Science:['science','space','research'],Sports:['sport','cricket','football','tennis'],Education:['education','school','university','exam']}[cat]||[];items=items.filter(x=>terms.some(t=>String(x.title).toLowerCase().includes(t)))}items=items.slice(0,count);window.__caItems=items;$('#caOut').innerHTML=items.map((x,i)=>`<div class="card"><h4>${i+1}. <a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a></h4><small>${esc(x.source||'Live News')} · ${esc(x.pubDate||'')}</small></div>`).join('')||'<div class="notice">No current-affairs items returned.</div>';if(items.length)$('#caOut').insertAdjacentHTML('beforeend','<button class="btn secondary" onclick="makeCurrentQuiz()">🤖 Create Daily Quiz</button>')}catch(e){try{const j=await api('ai-text',{type:'current_affairs',input:`${cat} current affairs for today. Give ${count} concise numbered headlines with source names and links when available.`,language:lang});window.__caItems=[];$('#caOut').innerHTML=`<div class="card"><h3>🤖 AI Current Affairs Briefing</h3><pre class="output">${esc(j.text||'No briefing available.')}</pre></div>`}catch(e2){$('#caOut').innerHTML='<div class="notice">'+esc(e2.message||e.message)+'</div>'}}}async function makeCurrentQuiz(){const items=window.__caItems||[];if(!items.length)return toast('Load headlines first.');try{const j=await api('ai-text',{type:'current_affairs',input:'Create 10 MCQs only from these headlines:\n'+items.map(x=>'- '+x.title).join('\n'),language:$('#caLang').value});$('#caOut').insertAdjacentHTML('beforeend','<pre class="output" style="margin-top:14px">'+esc(j.text)+'</pre>')}catch(e){toast(e.message)}}
function jobs(){return `<section class="hero"><h1>💼 Jobs & Competitive Exams</h1><p>Government jobs, recruitment notices and exam updates with AI summaries plus a live fallback.</p></section><div class="card"><select id="jobsCat" class="field"><option>All Government Jobs</option><option>Banking & Finance</option><option>SSC & Railways</option><option>UPSC & Civil Services</option><option>State Public Service Commissions</option></select><button class="btn" onclick="loadJobs()">🔍 Search Job & Exam Updates</button><div id="jobsOut" style="margin-top:15px"></div></div>`}async function loadJobs(){const cat=$('#jobsCat').value;$('#jobsOut').innerHTML='<div class="notice">Checking current updates…</div>';try{const j=await api('ai-text',{type:'jobs',input:cat,language:'English'});$('#jobsOut').innerHTML='<pre class="output">'+esc(j.text)+'</pre>'+share('NavaBharat AI jobs: '+cat)}catch(e){try{const r=await api('live-rss',{query:'India '+cat+' government jobs recruitment exam notification',language:'English',limit:15});$('#jobsOut').innerHTML=(r.items||[]).map(x=>`<div class="card"><h4><a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a></h4><small>${esc(x.source||'Live News')} · ${esc(x.pubDate||'')}</small></div>`).join('')||'<div class="notice">No job alerts found.</div>'}catch(e2){try{const j=await api('ai-text',{type:'jobs',input:cat+' current recruitment and exam updates for today. Use official sources when possible and clearly label uncertainty.',language:'English'});$('#jobsOut').innerHTML='<pre class="output">'+esc(j.text||'No job briefing available.')+'</pre>'+share('NavaBharat AI jobs: '+cat)}catch(e3){$('#jobsOut').innerHTML='<div class="notice">'+esc(e3.message||e2.message)+'</div>'}}}}
function creator(){return `<section class="hero"><h1>✨ Creator Studio</h1><p>Generate YouTube, Instagram, LinkedIn and X content with share-ready drafts.</p></section><div class="card"><input id="creatorTopic" class="field" placeholder="Content topic / idea"><select id="creatorPlatform" class="field"><option>YouTube Video Script & Metadata</option><option>Instagram Reel Caption & Hashtags</option><option>LinkedIn Thought Leadership Post</option><option>Twitter/X Thread</option></select><button class="btn" style="margin-top:12px" onclick="creatorGo()">✨ Generate Viral Content</button><div id="creatorOut" style="margin-top:18px"></div></div>`}async function creatorGo(){const topic=$('#creatorTopic').value.trim();if(!topic)return;$('#creatorOut').innerHTML='<div class="notice">Creating…</div>';try{const j=await api('ai-text',{type:'creator',input:topic+'\nPlatform: '+$('#creatorPlatform').value,language:'English'});$('#creatorOut').innerHTML=`<pre class="output">${esc(j.text)}</pre>${share('NavaBharat AI creator draft: '+topic)}`}catch(e){toast(e.message)}}
